# -*- coding: utf-8 -*-
# Second edition of the story: opens with the deal and its history, drops the treasury, pushback and closing-slide chapters.
import story2 as S0
from story1 import st, ROME, MECCA, WASH, LONDON, SLC, TIRUMALA, LUX, WORLD
OLD = {f["id"]: f for f in S0.FLOWS}
WITT = [12.6484, 51.8671]; AUGS = [10.8978, 48.3705]; MAINZ = [8.2473, 49.9929]

PARTS = [
 {"t": "The Deal: What You Give and What You Get", "d": "Money, obedience and your children go in. A promise that cannot be checked comes back. The institutions' own figures show where the money goes."},
 {"t": "The Top: Who Sits Above the Congregation", "d": "The people who decide what you are taught and where you may worship are not chosen by you."},
 {"t": "The State: What Governments Use Religion For", "d": "The government holds a power no church has: it can make a faith official, pay for it from your taxes and punish you for leaving it."},
 {"t": "The Sellers: How the Blessing Is Sold", "d": "Between the headquarters and the believer stand the people who ask for the money: the preacher on television and the agency that sells the pilgrimage."},
 {"t": "The Owners: Land, Tax and the Books Nobody Sees", "d": "Religious bodies are landlords and investors, and the law often lets them keep their accounts closed and their property untaxed."},
 {"t": "The Flock: What Happens Inside", "d": "Crime inside the institution is handled by the institution, and children are enrolled before they can judge."},
 {"t": "The Ballot: Faith as a Political Machine", "d": "A congregation is a crowd that can be told how to vote, and that is worth a great deal to a politician."},
]
FLOWS = []
def flow(**k): FLOWS.append(k)
def keep(fid, part, **changes):
    f = dict(OLD[fid]); f["part"] = part; f.update(changes); FLOWS.append(f); return f
def swap(f, pairs, field=None):
    """replace text in a chapter's own fields or in its slides; every replacement must hit"""
    for a, b in pairs:
        hit = False
        for k in (["sum", "bridge", "out", "rec", "kick"] if field is None else [field]):
            if a in f[k]: f[k] = f[k].replace(a, b); hit = True
        new = []
        for s in f["steps"]:
            if a in s["t"]: s = dict(s); s["t"] = s["t"].replace(a, b); hit = True
            new.append(s)
        f["steps"] = new
        assert hit, a[:60]

# ================================================================== PART 1 · THE DEAL
flow(id="deal", part=0, scope="world",
 title="What You Are Sold",
 kick="A tenth of your pay for a promise nobody can check, from an organisation that keeps its accounts closed.",
 sum="Look at religion the way you would look at anything else you pay for. You are asked to give money, often a fixed share of everything you earn, for your whole life. You are asked to give time and obedience, and to enrol your children. What you are promised in return is forgiveness, protection, blessing and a good outcome after you die. None of that can be inspected before you pay. Most of it is due only after death, when you cannot complain. The organisation that takes the money is also the only judge of whether it delivered.<br><br>In any other part of life this arrangement has a name. If a company took a tenth of your wages for a product it could not show you, refused to publish its accounts, told you that doubting it was a fault in you, and warned that leaving would cost you your family or worse, you would say you were being cheated. This map shows, using the religious institutions' own figures and the findings of courts and public inquiries, that this is how the religion system works. That is meant as a description of the system, not of one bad preacher or one bad church.<br><br>If you are a believer, this may feel like an attack on your faith. It is not. Nothing here says that God does not exist or that your prayers are worthless. The map is about the organisations that put themselves between you and what you believe, and charge you for it. The founders of the major religions gave the same warning, and one slide in this chapter tells you where to find it in your own scripture. Every figure on this map has a link to its source so that you can check it yourself.",
 bridge="The first slide shows how many people are inside the system and how they got there. The second gives the warnings written into the scriptures of four religions. The third follows a collection that Catholics are told is for the Pope's charity. The fourth shows what one church did with the tenth it asks of every member. The fifth gives a Christian research centre's own estimate of how much church money is stolen each year by the people handling it.",
 doubt="None of these figures comes from an enemy of religion. The split of the Pope's collection is published by the Vatican. The hidden fund is in an order of the United States market regulator, which the church did not contest. The theft estimate comes from a Christian seminary. The scripture references can be checked in your own copy.",
 out="Three people in four are members, most enrolled as children. The Pope's charity collection sends about eight euros in ten to offices. One church hid 32 billion dollars of savings from the members who tithed it. Christian researchers estimate that tens of billions given to churches are stolen every year. The next chapter shows this is not a modern accident. The business was built this way.",
 rec="You are asked for money, obedience and your children in exchange for a promise that cannot be checked, and the institutions' own figures show much of the money does not go where you were told.",
 roles=["Where the collection is spent", "Where the fund was hidden"],
 src=[{"t": "Vatican News, Peter's Pence 2024 report", "u": "https://www.vaticannews.va/en/vatican-city/news/2025-06/peter-s-pence-2024-shows-increase-in-support-for-pope-s-mission.print.html"},
      {"t": "Overseas Ministries Study Center, on the annual statistical table of world Christianity", "u": "https://omsc.ptsem.edu/world-christianity-its-annual-statistical-table-time/"}],
 steps=[
  st("2020", "The whole world", WORLD, 1.15, "Three People in Four Are Members",
   "Start with how many people are inside. Pew Research Center, a research organisation in Washington, counted the world's religious populations for 2020. It found that 75.8 per cent of people identified with a religion. Picture any four people on Earth: three belong to one. Christians were the largest group at 2.3 billion, followed by Muslims. Now ask how those people joined. Very few chose a religion as adults after comparing the options. Most were enrolled as babies or small children, by parents who had been enrolled the same way. So the largest membership organisations on Earth sign up most of their members before those members can read. Nothing else that takes your money for life is allowed to do that. Remember this through the rest of the map: when a religious body counts its members, it is mostly counting people who never applied.",
   "https://www.pewresearch.org/religion/2025/06/09/how-the-global-religious-landscape-changed-from-2010-to-2020/",
   pl=["pew"], w=1, ex=["pew2025"], note="This slide shows the whole world and shades no country, because the figure is a world total."),
  st("Scripture", "The whole world", WORLD, 1.15, "Your Own Scripture Warned You",
   "Before any figures, hear it from the sources believers trust most. The warning that religion would be turned into a way of taking money is written into the scriptures themselves. In the Christian Gospels, Jesus tells his followers that they received freely and must give freely (Matthew 10:8), and he drives the money-changers out of the temple, saying it had been made a den of robbers (Matthew 21:12-13). The Hebrew prophet Micah condemns priests who teach for a price (Micah 3:11). The Quran warns that many religious scholars and monks consume people's wealth wrongfully (9:34), and tells believers to follow those who ask no payment (36:21). The Buddha's rule for monks forbids them to accept gold and silver. So if this map makes you angry on behalf of your faith, notice whose side your faith's founders took. They were describing the same thing this map describes.",
   "", w=1, note="This slide shows the whole world and shades no country. Its sources are the passages named in the text, which can be read in any edition of each scripture."),
  st("2024", "Vatican City", ROME, 2.4, "Where the Pope's Collection Goes",
   "Now the figures. Once a year, Catholic parishes around the world take up a collection called Peter's Pence. The Vatican itself calls that Sunday the Day for the Pope's Charity. Most people who put money in the basket believe it goes to the poor. The Vatican publishes what happens to it. In 2024 the fund spent 75.4 million euros. Of that, 13.3 million went to aid projects for people in need. The other 61.2 million paid for the offices of the Holy See, the Church's central government in Rome. So out of every ten euros, about eight went to running an administration and fewer than two reached anyone in need. The year before, it was 90 million to the offices and 13 million to aid. The Vatican says the fund has always had both purposes. But a collection named for charity that spends four fifths on offices tells you how the system treats a gift.",
   "https://www.vaticannews.va/en/vatican-city/news/2025-06/peter-s-pence-2024-shows-increase-in-support-for-pope-s-mission.print.html",
   add={"Vatican City": 0, "Italy": 0}, pins=[[ROME[0], ROME[1], "Peter's Pence"]], pl=["holysee"], ex=["pence2024"]),
  st("1997-2023", "Salt Lake City", SLC, 3.0, "A Tenth of Your Pay, Saved Where You Could Not See It",
   "Regional Example: The Catholic collection is once a year. Some churches ask for far more. The Church of Jesus Christ of Latter-day Saints, based in Salt Lake City, asks every member for a tithe, which means a tenth of income. Members are told it supports the church's work. What was not spent was handed to the church's investment manager, Ensign Peak Advisors. American law required that manager to file public reports of the shares it held. Instead, from 1997 to 2019, it filed them under the names of thirteen shell companies, which are companies that exist only on paper. The government's market regulator found the church had approved this because it wanted to avoid disclosing how much it held. By 2018 the hidden portfolio was worth about 32 billion dollars. The two paid 5 million dollars in penalties in 2023. A family giving a tenth of a modest wage was funding a stock portfolio it was deliberately kept from knowing about.",
   "https://www.nbcnews.com/business/business-news/mormon-church-multibillion-investment-fund-sec-settlement-rcna71603",
   add={"United States": 1}, pins=[[SLC[0], SLC[1], "Ensign Peak Advisors"]], pl=["lds", "ensign", "sec"], ex=["secfine"], reg=True),
  st("2025", "The whole world", WORLD, 1.15, "Tens of Billions Stolen by the People in Charge",
   "The last two slides showed money used for something other than what givers were told. This one is about money that is simply taken. The Center for the Study of Global Christianity is part of Gordon-Conwell, a Christian seminary in the United States. Every year it publishes a table of figures on the world's churches. One line is called ecclesiastical crime: money stolen from churches and Christian organisations, mostly embezzled by people trusted to handle it. Its estimate for 2025 was 92 billion dollars, against 1,383 billion given to Christian causes. That is about one dollar in every fifteen. Its 2026 edition puts the figure near 70 billion, up from 19 billion in the year 2000. In an earlier year the centre noted that the amount stolen was larger than everything spent on foreign missions worldwide. These are Christians counting their own churches. They treat theft by insiders as a normal, measurable part of how church money moves.",
   "https://omsc.ptsem.edu/world-christianity-its-annual-statistical-table-time/",
   pl=["csgc"], w=1, ex=["csgc2025"], note="This slide shows the whole world and shades no country, because the estimate is a world total and is not published country by country."),
 ])

flow(id="history", part=0, scope="eu",
 title="How the Business Was Built",
 kick="Forgiveness was sold to build a cathedral, a tenth was taken by law for a thousand years, and a church fund grew from the slave trade.",
 sum="It would be comforting to think that money problems in religion are recent, caused by a few modern preachers. The record says otherwise. For most of history, in the part of the world where records are best kept, religious payment was not a gift at all. It was a price or a tax, and it was enforced.<br><br>This matters to you now for a practical reason. Wealth does not disappear. A fund built three hundred years ago is still earning today. A cathedral paid for by selling forgiveness is still standing and still collecting visitors. The habits of thinking did not disappear either. The idea that you owe a tenth, that a payment can improve your position with God, and that the institution's wealth is not your business were all taught for centuries by organisations that profited from them. When a preacher today tells you giving will be rewarded, he is using a method with a very long history.<br><br>The three slides in this chapter are from Christian Europe, because that is where the paperwork survives and where the churches themselves have published it. The pattern is not limited to one faith, and later chapters show temples, mosques and newer movements doing the same things today. Each slide here ends with what it left behind that you can still see.",
 bridge="The first slide shows forgiveness being sold to pay for a building in Rome. The second shows the tenth being collected by law in England for more than a thousand years. The third follows one church fund from the slave trade of the 1700s to an investment office in London today.",
 doubt="The sale of forgiveness is described in the Encyclopaedia Britannica and was ended by a pope. The tithe laws are Acts of the British Parliament. The link between the Church of England's fund and the slave trade was researched and published by the Church's own investment body, which apologised for it.",
 out="Forgiveness was sold until 1567. A tenth was taken by law in England until 1936. A fund that held slave-trade investments in 1777 is now worth 11.6 billion pounds. The system you were born into was built as a way of collecting. The next part shows who sits at the top of it.",
 rec="For centuries religious payment was a price or a tax enforced by law, and the buildings and funds it paid for are still standing and still earning.",
 roles=["Where the money went", "Where it was collected"],
 src=[{"t": "Encyclopaedia Britannica, Indulgence", "u": "https://www.britannica.com:443/topic/indulgence"},
      {"t": "Encyclopaedia Britannica, Tithe", "u": "https://www.britannica.com/topic/tithe"},
      {"t": "Church Times, Church Commissioners to set aside £100 million", "u": "https://www.churchtimes.co.uk/articles/2023/13-january/news/uk/church-commissioners-to-set-aside-100-million-to-compensate-for-slave-trade-links"}],
 steps=[
  st("1517", "Rome", ROME, 3.2, "Forgiveness for Sale",
   "The last chapter showed where religious money goes today. This one shows how old the method is. In the Catholic teaching of the time, a soul might spend a long period being punished after death before reaching heaven. An indulgence was a certificate from the Church that shortened that time. By the 1500s indulgences were being sold for cash. In 1517 Pope Leo X offered one to raise money for rebuilding St Peter's Basilica in Rome. In Germany, half of what was collected went to Rome and half went to repay a banking family that had lent an archbishop the money to buy his position. A monk named Martin Luther objected. In a list of ninety-five points he asked why the Pope, who was richer than anyone, did not build the church with his own money and not that of poor believers. The sale was banned by a later pope in 1567. St Peter's is still there. Its builders were paid with the fear of ordinary people about what would happen to them after death.",
   "https://www.britannica.com:443/topic/indulgence",
   add={"Vatican City": 0, "Italy": 0, "Germany": 1}, arcs=[[WITT, ROME], [MAINZ, AUGS]], an=[["Germany", "Rome"], ["Mainz", "Augsburg"]],
   pins=[[ROME[0], ROME[1], "St Peter's Basilica"], [WITT[0], WITT[1], "Wittenberg"], [AUGS[0], AUGS[1], "The bank, Augsburg"]], pl=["holysee"], ex=["indulgence1517"]),
  st("794-1936", "London", LONDON, 3.2, "A Tenth Taken by Law for Eleven Centuries",
   "Regional Example: Selling forgiveness depended on fear. The tithe did not even depend on that. A tithe is a tenth of what you produce or earn, paid to the church. In England it began as a voluntary offering. In the year 794 a king made it compulsory in his kingdom, and within a century it was compulsory everywhere in the country. For the next thousand years a farmer who did not hand over a tenth of the harvest could be taken to court, and the courts that heard the case belonged to the church. In 1836 the payment in crops was changed to a yearly charge in money. That charge was abolished only in 1936. The same system ended in Ireland in 1871 and in Italy by 1887. So for most of the history of Christianity in Europe, giving to the church was a tax that you could be punished for not paying. The collection plate passed round today is what was left when the law was taken away.",
   "https://www.historytoday.com/archive/tithes-country-life",
   add={"United Kingdom": 1}, pins=[[LONDON[0], LONDON[1], "England"]], pl=["cofe"], ex=["tithe1936"], reg=True),
  st("1704-2025", "London", LONDON, 3.2, "A Church Fund That Grew From the Slave Trade",
   "Regional Example: Money collected for centuries has to be kept somewhere. In 1704 the Church of England set up a fund called Queen Anne's Bounty to support its poorer clergy. The fund invested in the South Sea Company, which shipped enslaved Africans across the Atlantic. The Church's own researchers found that by 1777 the fund held South Sea investments worth about 724 million pounds in today's money, and that the company carried some 34,000 enslaved people. The fund's managers knew what the company did. In 1948 Queen Anne's Bounty was merged into a new body, the Church Commissioners, who still manage the Church of England's money. In 2023 they published this history, apologised, and set aside 100 million pounds in response. Their fund was worth 11.6 billion pounds at the end of 2025. The amount set aside is less than one pound in every hundred. Money made from human beings three centuries ago was never given back. It was invested, and it is still growing.",
   "https://www.churchtimes.co.uk/articles/2023/13-january/news/uk/church-commissioners-to-set-aside-100-million-to-compensate-for-slave-trade-links",
   add={"United Kingdom": 1}, pins=[[LONDON[0], LONDON[1], "Church Commissioners"]], pl=["commissioners", "cofe"], ex=["bounty2023"], reg=True),
 ])

# ================================================================== PART 2 · THE TOP
flow(id="command", part=1, scope="world",
 title="The Chain of Command Above Your Place of Worship",
 kick="You do not choose the people who decide what you are taught, and one government decides who may enter Islam's holiest city.",
 sum="A place of worship feels local. It has a building, a priest, imam, pastor or monk, a congregation and a weekly service, and it is easy to assume that the people in the room run it. In most religions they do not. The person at the front was sent, approved or licensed by someone higher up. What that person may teach was decided elsewhere. Where the collection goes after it leaves the plate was decided elsewhere too.<br><br>This is the first thing to understand about the structure, because everything in the last two chapters depends on it. Money can be moved away from the purpose you gave it for only if you have no say over the people moving it. In a club or a town council, members can vote the leaders out and demand to see the books. In most religious bodies there is no such vote. Authority runs downward from a headquarters, or from a government ministry where the state has taken that role. The member's part is to attend, obey and give.<br><br>There are two main ways of holding power at the top. One is to control people, by deciding who is allowed to lead. The other is to control a place, by owning the ground that believers are told they must visit. The two slides show the largest example of each.",
 bridge="The first slide shows a church in which one office chooses the regional leaders for 1.4 billion people. The second shows a government that controls entry to a city that Muslims everywhere are asked to visit.",
 doubt="The number of Catholics and bishops comes from the Vatican's own yearbook. The pilgrim numbers and the permit rule come from the Saudi government.",
 out="One office in Rome chooses the bishops of the world's largest church, and one government decides who may enter Mecca. In neither case does the believer have a vote. An organisation run from above needs help to hold its position, and the strongest helper is the government. That is the next part.",
 rec="The leaders of most religions are appointed from above, and the holiest places are controlled by whoever owns the ground, so the member has no vote.",
 roles=["Where the headquarters is", "Where the holy place is"],
 src=[{"t": "Vatican News, Pontifical Yearbook 2025", "u": "https://www.vaticannews.va/en/vatican-city/news/2025-03/pontifical-yearbook-2025-priests-religious-statistics.html"}],
 steps=[
  st("2023", "Vatican City", ROME, 2.4, "You Did Not Choose Your Bishop",
   "The last part showed where the money goes. This one shows why members cannot stop it. Take the largest single religious organisation on Earth. The Vatican's own yearbook counts 1.406 billion Catholics at the end of 2023 and 5,430 bishops. A bishop runs the Church in a region: he assigns the priests to each parish and controls the Church's property there. That is one bishop for about every 260,000 Catholics. None of those Catholics voted for him. Bishops are appointed from Rome, by the Pope. So if you are Catholic, the priest in your parish answers to a bishop, and the bishop answers to an office you had no part in choosing and cannot remove. If the bishop closes your church, sells its land or moves a priest, there is no election at which you can object. The money in the collection basket goes up the same chain that you have no vote in.",
   "https://www.vaticannews.va/en/vatican-city/news/2025-03/pontifical-yearbook-2025-priests-religious-statistics.html",
   add={"Vatican City": 0, "Italy": 0}, pins=[[ROME[0], ROME[1], "The Holy See"]], pl=["holysee"]),
  st("2024", "Mecca", MECCA, 2.6, "One Government Holds the Gate to Mecca",
   "The Catholic Church holds power by choosing who leads. A second way needs no appointments: own the ground that a religion tells its followers to visit. Islam asks every Muslim who is able to travel once in their life to Mecca, for the pilgrimage called the Hajj. Mecca is inside Saudi Arabia. So a duty shared by about two billion people can be carried out only with one government's permission. Saudi rules require a special pilgrim visa, and the government decides how many are issued. In 2024 its officials counted about 1.83 million pilgrims, more than 1.6 million of them from abroad. In 2019 there were more than 2.4 million. If you are a Muslim in Indonesia, Nigeria or France, you cannot complete this duty without the consent of a government you do not vote for. Whoever controls a gate like that can decide who enters and what entering costs. A later chapter shows what happened to the people left outside it.",
   "https://www.thenationalnews.com/news/gulf/2024/06/24/hajj-deaths-saudi-arabia-egypt/",
   add={"Saudi Arabia": 1}, pins=[[MECCA[0], MECCA[1], "Mecca"]], pl=["hajjmin", "twoholy"]),
 ])

